import unittest
from pairs import parse_pairs
class Acceptance(unittest.TestCase):
 def test_empty(self): self.assertEqual(parse_pairs(["", "  "]), {})
 def test_first_equals(self): self.assertEqual(parse_pairs(["x=y=z"]), {"x":"y=z"})
 def test_duplicate(self): self.assertEqual(parse_pairs(["x=1", "x=2", "z="]), {"x":"2","z":""})
 def test_invalid(self):
  for lines in [["no separator"], [" =1"]]:
   with self.assertRaises(ValueError): parse_pairs(lines)
 def test_unchanged(self):
  a=["a=b"]; parse_pairs(a); self.assertEqual(a,["a=b"])

