import unittest
from intervals import merge_intervals
class Acceptance(unittest.TestCase):
 def test_empty(self): self.assertEqual(merge_intervals([]), [])
 def test_touching(self): self.assertEqual(merge_intervals([(3,4),(1,3)]), [(1,4)])
 def test_disjoint(self): self.assertEqual(merge_intervals([(5,6),(1,2)]), [(1,2),(5,6)])
 def test_zero_and_nested(self): self.assertEqual(merge_intervals([(2,2),(1,5),(2,3)]), [(1,5)])
 def test_reverse(self):
  with self.assertRaises(ValueError): merge_intervals([(3,1)])
 def test_unchanged(self):
  a=[(4,5),(1,2)]; merge_intervals(a); self.assertEqual(a,[(4,5),(1,2)])
